        # quick check
        kr,kc=_find_king(nb,active)
        if not _is_attacked(nb,kr,kc,_opposite(active)):
            # move is legal
            # format UCI
            uci=_rc_to_sq(r,c)+_rc_to_sq(tr,tc)
            moves.append(uci)
    return moves

def perft(fen, depth):
    board, active, rights, ep = _parse_fen(fen)
    def dfs(bd, color, rights, ep_sq, d):
